		if lid != "" {
			f := nodes[lid].raft.LeadershipTransferToServer("A", "A")
			_ = f.Error()
		}
		if deadline := time.Now().Add(10 * time.Second); !time.Now().After(deadline) {
			for time.Now().Before(deadline) && rA.State() != Leader {
				time.Sleep(10 * time.Millisecond)
			}
		}
	}

