	barrier := rA.Barrier(3 * time.Second)
	if err := barrier.Error(); err != nil {
		t.Fatalf("barrier: %v", err)
	}
	snapF := rA.Snapshot()
	if err := snapF.Error(); err != nil {
		t.Fatalf("snapshot: %v", err)
	}
	snapList, _ := nodes["A"].snaps.List()
	if len(snapList) == 0 {
		t.Fatalf("no snapshot on A")
	}
