r.setCurrentTerm(currentTerm)
r.setLastLog(lastLog.Index, lastLog.Term)

// Attempt to restore a snapshot if there are any.
if err := r.restoreSnapshot(); err != nil {
	return nil, err
}

if err := r.restoreFromCommittedLogs(); err != nil {
